// ─── フェーズ1: 自分の答え（選択式のみ・選択肢はAIが自動生成）──────
// mode/category: 選択肢・別の質問を作るために使う
function OwnRound({ player, color, mode, category, questions, onDone }) {
  const [idx, setIdx] = useState(0);
  const [localQ, setLocalQ] = useState(questions);
  const [own, setOwn] = useState(questions.map(() => ""));
  const [loading, setLoading] = useState(null); // "skip" | null
  const inFlight = useRef(new Set());
  const q = localQ[idx], last = idx === localQ.length - 1;
  const ready = own[idx].trim() && !loading && !!q.choices;
  const set = (v) => { const c = [...own]; c[idx] = v; setOwn(c); };

  // 選択肢を裏で生成（ブロックしない）。読み込み中でも他の問題を先読みできる
  const ensure = async (i) => {
    if (localQ[i].choices || inFlight.current.has(i)) return;
    inFlight.current.add(i);
    const ch = await generateChoicesForQuestion(localQ[i].question, category === CAT_SPICY);
    if (ch) {
      setLocalQ((prev) => { if (prev[i].choices) return prev; const nx = [...prev]; nx[i] = { ...nx[i], choices: ch, generated: true }; return nx; });
    }
    inFlight.current.delete(i);
  };

  // マウント時に全問を先読み。以降はほぼ待ちなしで進める
  useEffect(() => {
    localQ.forEach((qq, i) => { if (!qq.choices) ensure(i); });
    // eslint-disable-next-line
  }, []);
  // 表示中の問題は最優先で確保（スキップ後などの保険）
  useEffect(() => { if (!localQ[idx].choices) ensure(idx); /* eslint-disable-next-line */ }, [idx, localQ]);

  const skip = () => {
    const avoid = localQ.map((x) => x.question);
    const gen = pickQuestions(mode, category, 1, avoid); // 固定の質問集から
    const nq = gen && gen[0] ? gen[0] : null;
    if (nq) {
      setLocalQ((prev) => { const a = [...prev]; a[idx] = nq; return a; });
      setOwn((prev) => { const a = [...prev]; a[idx] = ""; return a; });
    }
  };

  const subtle = { background: "#fff", color: C.muted, border: `1.5px solid ${C.line}`, fontWeight: 700, fontSize: 13 };

  return (
    <div className="w-full">
      <div className="flex items-center gap-2 mb-2">
        <Dot color={color} /><span style={{ color, fontWeight: 800 }}>{player}</span>
        <span style={{ color: C.muted, fontSize: 13 }}>の本音</span>
      </div>
      <div className="rounded-full px-3 py-2 mb-3 text-center" style={{ background: "#FBEFEA", color: C.a, fontSize: 13, fontWeight: 800, border: `1px solid ${C.aSoft}` }}>
        🙈 相手に見せないで
      </div>
      <Progress idx={idx} total={localQ.length} color={color} />
      <div className="rounded-3xl p-5 mb-4" style={{ background: "#fff", boxShadow: "0 10px 30px rgba(51,40,58,.08)" }}>
        <div style={{ fontSize: 20, fontWeight: 800, color: C.ink, lineHeight: 1.4 }}>{q.question}</div>
        <div className="mt-5">
          <label style={{ fontSize: 13, color, fontWeight: 700 }}>あなた（{player}）のこたえを選ぶ</label>
          {q.choices ? (
            <div className="flex flex-col gap-2 mt-2">
              {q.choices.map((opt) => {
                const on = own[idx] === opt;
                return (
                  <button key={opt} onClick={() => set(opt)} className="rounded-2xl px-4 py-3 text-left"
                    style={{ border: `2px solid ${on ? color : C.line}`, background: on ? color : "#fff", color: on ? "#fff" : C.ink, fontWeight: 700, fontSize: 16 }}>{opt}</button>
                );
              })}
            </div>
          ) : (
            <div className="flex items-center gap-2 py-6 justify-center" style={{ color: C.muted, fontWeight: 700 }}>
              <span style={{ fontSize: 20 }}>🪄</span> 選択肢を用意中…
            </div>
          )}
        </div>

        <div className="flex flex-wrap gap-2 mt-4">
          <button onClick={skip} disabled={!!loading} className="rounded-full px-4 py-2" style={{ ...subtle, opacity: loading ? 0.6 : 1 }}>
            {loading === "skip" ? "変更中…" : "🔄 別の質問にする"}
          </button>
        </div>
        <div style={{ fontSize: 12, color: C.muted, marginTop: 10 }}>※あとで相手がこの答えを当てにきます</div>
      </div>

      <div className="flex gap-3">
        {idx > 0 && (
          <button onClick={() => setIdx(idx - 1)} className="rounded-full px-5 py-3"
            style={{ background: "#fff", color: C.muted, border: `1.5px solid ${C.line}`, fontWeight: 700 }}>戻る</button>
        )}
        <button disabled={!ready} onClick={() => (last ? onDone(localQ, own) : setIdx(idx + 1))}
          className="rounded-full px-5 py-3 flex-1"
          style={{ background: ready ? color : C.line, color: "#fff", fontWeight: 800, fontSize: 16, opacity: ready ? 1 : 0.7 }}>
          {last ? "入力おわり" : "次へ"}
        </button>
      </div>
    </div>
  );
}

// ─── フェーズ2: 相手の答えを選ぶ ───────────────────────────
function GuessRound({ player, other, color, otherColor, questions, options, onDone }) {
  const [idx, setIdx] = useState(0);
  const [pick, setPick] = useState(questions.map(() => null));
  const last = idx === questions.length - 1;
  const opts = options[idx];
  const ready = opts && pick[idx] != null;
  const choose = (v) => { const c = [...pick]; c[idx] = v; setPick(c); };
  return (
    <div className="w-full">
      <div className="flex items-center gap-2 mb-2">
        <Dot color={color} /><span style={{ color, fontWeight: 800 }}>{player}</span>
        <span style={{ color: C.muted, fontSize: 13 }}>が {other} を予想</span>
      </div>
      <div className="rounded-full px-3 py-2 mb-3 text-center" style={{ background: C.bSoft, color: C.b, fontSize: 13, fontWeight: 800 }}>
        👀 相手と一緒に見てOK
      </div>
      <Progress idx={idx} total={questions.length} color={color} />
      <div className="rounded-3xl p-5 mb-4" style={{ background: "#fff", boxShadow: "0 10px 30px rgba(51,40,58,.08)" }}>
        <div style={{ fontSize: 15, color: otherColor, fontWeight: 700 }}>{other} の…</div>
        <div style={{ fontSize: 20, fontWeight: 800, color: C.ink, lineHeight: 1.4, marginBottom: 14 }}>{questions[idx].question}</div>
        {opts ? (
          <div className="flex flex-col gap-2">
            {opts.map((opt) => {
              const on = pick[idx] === opt;
              return (
                <button key={opt} onClick={() => choose(opt)} className="rounded-2xl px-4 py-3 text-left"
                  style={{ border: `2px solid ${on ? color : C.line}`, background: on ? color : "#fff", color: on ? "#fff" : C.ink, fontWeight: 700, fontSize: 16 }}>{opt}</button>
              );
            })}
          </div>
        ) : (
          <div className="flex items-center gap-2 py-6 justify-center" style={{ color: C.muted, fontWeight: 700 }}>
            <span style={{ fontSize: 22 }}>💗</span> 選択肢を準備中…
          </div>
        )}
      </div>
      <div className="flex gap-3">
        {idx > 0 && (
          <button onClick={() => setIdx(idx - 1)} className="rounded-full px-5 py-3"
            style={{ background: "#fff", color: C.muted, border: `1.5px solid ${C.line}`, fontWeight: 700 }}>戻る</button>
        )}
        <button disabled={!ready} onClick={() => (last ? onDone(pick) : setIdx(idx + 1))}
          className="rounded-full px-5 py-3 flex-1"
          style={{ background: ready ? color : C.line, color: "#fff", fontWeight: 800, fontSize: 16, opacity: ready ? 1 : 0.7 }}>
          {last ? "予想おわり" : "次へ"}
        </button>
      </div>
    </div>
  );
}

// ─── メイン ───────────────────────────────────────────────
export default function App() {
  const [phase, setPhase] = useState("home");
  const [nameA, setNameA] = useState("");
  const [nameB, setNameB] = useState("");
  const [mode, setMode] = useState("normal");
  const [category, setCategory] = useState("なんでも");
  const [spicyUnlocked, setSpicyUnlocked] = useState(false);
  const [loveTaps, setLoveTaps] = useState(0);
  useEffect(() => { (async () => { try { const r = await window.storage.get("spicy-unlocked"); if (r && r.value) setSpicyUnlocked(true); } catch (e) {} })(); }, []);
  const [questions, setQuestions] = useState([]); // 元の共通質問 [{question, choices}]
  const [qA, setQA] = useState(null); // Aが実際に答えた質問（スキップ等で変わりうる）
  const [qB, setQB] = useState(null); // Bが実際に答えた質問
  const [ownA, setOwnA] = useState(null);
  const [ownB, setOwnB] = useState(null);
  const [optsForA, setOptsForA] = useState(null); // Aが Bを当てる選択肢
  const [optsForB, setOptsForB] = useState(null); // Bが Aを当てる選択肢
  const [guessA, setGuessA] = useState(null);
  const [guessB, setGuessB] = useState(null);
  const [copied, setCopied] = useState(false);
  const [deck, setDeck] = useState([]);      // 会話カードモードの山札
  const [cardIdx, setCardIdx] = useState(0); // 現在めくっているカードの位置
  const [flipKey, setFlipKey] = useState(0); // カードをめくるたびに増やしてフリップ再生

  const bg = {
    minHeight: "100vh", fontFamily: FONT, color: C.ink, padding: "24px 18px 48px",
    background: `linear-gradient(150deg, ${C.aSoft} 0%, #FBF6F2 45%, ${C.bSoft} 100%)`,
  };
  const wrap = { maxWidth: 460, margin: "0 auto" };

  const start = async () => {
    setPhase("gen");
    const key = `${mode}-${category}`;
    const avoid = await loadAsked(key);
    const qs = await generateQuestions(mode, category, QCOUNT, avoid);
    setQuestions(qs);
    saveAsked(key, [...avoid, ...qs.map((q) => q.question)]);
    setPhase("introOwnA");
  };

  // 自由回答の選択肢を BATCH 問ずつ裏で生成し、出来たものから流し込む。
  // ダミーの穴埋めは「答えた本人の他の回答」だけを使う（予想する側=自分の回答は絶対に混ぜない）
  const fillDecoys = async (setter, qArr, correct) => {
    const spicy = category === CAT_SPICY;
    const open = [];
    qArr.forEach((q, i) => { if (!q.choices) open.push({ i, question: q.question, answer: correct[i] }); });
    const clean = (list, real) => (list || []).map((d) => (d || "").trim()).filter((d) => d && d !== (real || "").trim());
    for (let s = 0; s < open.length; s += BATCH) {
      const chunk = open.slice(s, s + BATCH);
      const map = await generateDecoys(chunk.map((c) => ({ question: c.question, answer: c.answer })), spicy);
      await Promise.all(chunk.map(async (c, ci) => {
        let dummies = clean(map[ci], c.answer);
        if (dummies.length < 3) {
          // 足りない問題だけ、1問ずつの簡易生成でフォロー
          const ch = await generateChoicesForQuestion(c.question, spicy);
          dummies = [...new Set([...dummies, ...clean(ch, c.answer)])];
        }
        setter((prev) => { const nx = [...prev]; nx[c.i] = buildOptions(c.answer, dummies); return nx; });
      }));
    }
  };

  // 両者の回答が揃った時点で呼ぶ。全画面待ちはせず、すぐ予想フェーズへ。
  const startGuessing = (qAx, aAns, qBx, bAns) => {
    // Aは Bの質問を予想 / Bは Aの質問を予想。選択式は即セット、自由回答は未生成で先へ
    setOptsForA(qBx.map((q) => (q.choices ? shuffle(q.choices) : undefined)));
    setOptsForB(qAx.map((q) => (q.choices ? shuffle(q.choices) : undefined)));
    setPhase("introGuessA");
    (async () => {
      await fillDecoys(setOptsForA, qBx, bAns);
      await fillDecoys(setOptsForB, qAx, aAns);
    })();
  };

  const replay = () => {
    setQA(null); setQB(null); setOwnA(null); setOwnB(null); setOptsForA(null); setOptsForB(null); setGuessA(null); setGuessB(null);
    start();
  };
  const reset = () => {
    setPhase("setup"); setQuestions([]);
    setQA(null); setQB(null); setOwnA(null); setOwnB(null); setOptsForA(null); setOptsForB(null); setGuessA(null); setGuessB(null);
  };
  const goHome = () => {
    setPhase("home"); setQuestions([]); setDeck([]); setCardIdx(0);
    setQA(null); setQB(null); setOwnA(null); setOwnB(null); setOptsForA(null); setOptsForB(null); setGuessA(null); setGuessB(null);
  };

  // ── 会話カードモード ──
  const startCards = () => {
    const pool = getPool(mode, category);
    setDeck(shuffle(pool));
    setCardIdx(0);
    setFlipKey((k) => k + 1);
    setPhase("cards");
  };
  const nextCard = () => {
    setCardIdx((i) => {
      const n = i + 1;
      if (n >= deck.length) { setDeck((d) => shuffle(d)); return 0; } // 一巡したらシャッフルして最初へ
      return n;
    });
    setFlipKey((k) => k + 1);
  };
  const prevCard = () => {
    setCardIdx((i) => Math.max(0, i - 1)); // 先頭ではそれ以上戻らない
    setFlipKey((k) => k + 1);
  };
  const shuffleCards = () => { setDeck((d) => shuffle(d)); setCardIdx(0); setFlipKey((k) => k + 1); };
  const shareApp = async () => {
    const url = (typeof window !== "undefined" && window.location)
      ? window.location.origin + window.location.pathname : "";
    const shareData = { title: "価値観あてクイズ", text: "お互いの価値観をどれだけ当てられる？2人用の価値観あてクイズ。一緒にやってみよ！", url };
    try {
      if (typeof navigator !== "undefined" && navigator.share) {
        await navigator.share(shareData);
        return;
      }
    } catch (e) { return; } // 共有ダイアログをキャンセルした場合など
    try {
      if (typeof navigator !== "undefined" && navigator.clipboard) {
        await navigator.clipboard.writeText(url);
      } else if (typeof window !== "undefined") {
        window.prompt("このリンクをコピーして共有してね", url);
        return;
      }
    } catch (e) {
      if (typeof window !== "undefined") { window.prompt("このリンクをコピーして共有してね", url); return; }
    }
    setCopied(true);
    setTimeout(() => setCopied(false), 1800);
  };

  // ── HOME（モード選択）──
  if (phase === "home") {
    return (
      <div style={bg}><div style={wrap}>
        <div className="flex justify-center mb-2"><HeartMeter pct={62} /></div>
        <h1 style={{ fontSize: 30, fontWeight: 800, textAlign: "center", lineHeight: 1.25 }}>価値観あてクイズ</h1>
        <p style={{ textAlign: "center", color: C.muted, marginTop: 6, marginBottom: 22, lineHeight: 1.6 }}>
          ふたりで楽しむ、価値観の遊び。<br />モードを選んでね。
        </p>
        <div className="flex flex-col gap-4">
          <button onClick={() => setPhase("setup")} className="rounded-3xl p-5 text-left"
            style={{ background: "#fff", border: `2px solid ${C.a}`, boxShadow: "0 10px 30px rgba(51,40,58,.08)" }}>
            <div className="flex items-center gap-3">
              <div className="rounded-2xl flex items-center justify-center" style={{ width: 52, height: 52, flex: "0 0 auto", background: C.aSoft, fontSize: 26 }}>💘</div>
              <div>
                <div style={{ fontSize: 18, fontWeight: 800, color: C.ink }}>価値観あてクイズ</div>
                <div style={{ fontSize: 13, color: C.muted, marginTop: 3, lineHeight: 1.5 }}>お互いの答えを予想して、相性を判定。2人で交代しながら遊ぶ本格モード。</div>
              </div>
            </div>
          </button>
          <button onClick={() => setPhase("cardsSetup")} className="rounded-3xl p-5 text-left"
            style={{ background: "#fff", border: `2px solid ${C.b}`, boxShadow: "0 10px 30px rgba(51,40,58,.08)" }}>
            <div className="flex items-center gap-3">
              <div className="rounded-2xl flex items-center justify-center" style={{ width: 52, height: 52, flex: "0 0 auto", background: C.bSoft, fontSize: 26 }}>🃏</div>
              <div>
                <div style={{ fontSize: 18, fontWeight: 800, color: C.ink }}>会話カード</div>
                <div style={{ fontSize: 13, color: C.muted, marginTop: 3, lineHeight: 1.5 }}>質問カードを1枚ずつめくって、話の種に。当てっこ無しで気軽におしゃべり。</div>
              </div>
            </div>
          </button>
        </div>
        <button onClick={shareApp} className="rounded-full w-full mt-6 py-3"
          style={{ background: "#fff", color: C.muted, border: `1.5px solid ${C.line}`, fontWeight: 700, fontSize: 15 }}>
          {copied ? "リンクをコピーしました ✓" : "🔗 このアプリのリンクを共有"}
        </button>
      </div></div>
    );
  }

  // ── SETUP ──
  if (phase === "setup") {
    const field = { width: "100%", border: `1.5px solid ${C.line}`, borderRadius: 14, padding: "12px 14px", fontSize: 16, background: "#fff", outline: "none", color: C.ink };
    const ok = nameA.trim() && nameB.trim();
    return (
      <div style={bg}><div style={wrap}>
        <button onClick={goHome} className="mb-2" style={{ background: "none", border: "none", color: C.muted, fontWeight: 700, fontSize: 14, padding: "4px 2px" }}>← モード選択にもどる</button>
        <div className="flex justify-center mb-2"><HeartMeter pct={62} /></div>
        <h1 style={{ fontSize: 30, fontWeight: 800, textAlign: "center", lineHeight: 1.25 }}>価値観あてクイズ</h1>
        <p style={{ textAlign: "center", color: C.muted, marginTop: 6, marginBottom: 16, lineHeight: 1.6 }}>
          相手のことを<b>どれだけ知ってるか</b>を当て合う、2人用ゲーム。<br />スマホ1台を交代で使います。
        </p>
        <div className="rounded-3xl p-4 mb-4" style={{ background: "#fff", boxShadow: "0 10px 30px rgba(51,40,58,.08)" }}>
          <div style={{ fontSize: 13, fontWeight: 800, color: C.ink, marginBottom: 10 }}>遊び方（かんたん3ステップ）</div>
          {[
            { n: "1", c: C.a, t: "自分の答えを選ぶ", d: "「好きな食べ物は？」などに、二人がこっそり選択肢から回答" },
            { n: "2", c: C.b, t: "相手の答えを予想", d: "相手が何と答えたかを4択から選ぶ" },
            { n: "3", c: C.gold, t: "相性を判定！", d: "当てた数で二人の相性が決まり、評価キャラが登場" },
          ].map((s, i) => (
            <div key={i} className="flex items-start gap-3" style={{ marginBottom: i < 2 ? 10 : 0 }}>
              <div className="rounded-full flex items-center justify-center" style={{ width: 26, height: 26, flex: "0 0 auto", background: s.c, color: "#fff", fontWeight: 800, fontSize: 14 }}>{s.n}</div>
              <div>
                <div style={{ fontSize: 15, fontWeight: 800, color: C.ink }}>{s.t}</div>
                <div style={{ fontSize: 12.5, color: C.muted, lineHeight: 1.5 }}>{s.d}</div>
              </div>
            </div>
          ))}
        </div>
        <div className="rounded-3xl p-5" style={{ background: "#fff", boxShadow: "0 10px 30px rgba(51,40,58,.08)" }}>
          <label style={{ fontSize: 13, color: C.a, fontWeight: 700 }}>プレイヤー1の名前</label>
          <input style={field} className="mt-1 mb-4" value={nameA} onChange={(e) => setNameA(e.target.value)} placeholder="れい" />
          <label style={{ fontSize: 13, color: C.b, fontWeight: 700 }}>プレイヤー2の名前</label>
          <input style={field} className="mt-1" value={nameB} onChange={(e) => setNameB(e.target.value)} placeholder="ゆう" />
          <div style={{ fontSize: 13, color: C.ink, fontWeight: 700, marginTop: 18, marginBottom: 8 }}>難易度（全5問）</div>
          <div className="flex flex-col gap-2">
            {MODES.map((m) => {
              const on = mode === m.key;
              return (
                <button key={m.key} onClick={() => setMode(m.key)} className="rounded-2xl px-4 py-3 text-left"
                  style={{ border: `2px solid ${on ? C.ink : C.line}`, background: on ? C.ink : "#fff" }}>
                  <div style={{ fontSize: 16, fontWeight: 800, color: on ? "#fff" : C.ink }}>{m.label}</div>
                  <div style={{ fontSize: 12, color: on ? "#EAD9DF" : C.muted, marginTop: 2 }}>{m.desc}</div>
                </button>
              );
            })}
          </div>
          <div style={{ fontSize: 13, color: C.ink, fontWeight: 700, marginTop: 18, marginBottom: 8 }}>カテゴリ{spicyUnlocked ? " 🔓" : ""}</div>
          <div className="flex flex-wrap gap-2">
            {(spicyUnlocked ? [...CATEGORIES, CAT_SPICY] : CATEGORIES).map((c) => {
              const on = category === c;
              return (
                <button key={c} onClick={() => {
                  setCategory(c);
                  if (c === CAT_LOVE && !spicyUnlocked) {
                    const n = loveTaps + 1; setLoveTaps(n);
                    if (n >= 20) { setSpicyUnlocked(true); try { window.storage.set("spicy-unlocked", "1"); } catch (e) {} }
                  }
                }} className="rounded-full px-4 py-2"
                  style={{ fontSize: 14, fontWeight: 700, border: `1.5px solid ${on ? C.ink : C.line}`, background: on ? C.ink : "#fff", color: on ? "#fff" : C.muted }}>{c}</button>
              );
            })}
          </div>
          {category === CAT_SPICY && (
            <div style={{ fontSize: 12, color: C.muted, marginTop: 8 }}>※18歳以上向け。大人同士で楽しんでね</div>
          )}
        </div>
        <button disabled={!ok} onClick={start} className="rounded-full w-full mt-5 py-4"
          style={{ background: ok ? C.ink : C.line, color: "#fff", fontWeight: 800, fontSize: 17, opacity: ok ? 1 : 0.7 }}>はじめる</button>
        <button onClick={shareApp} className="rounded-full w-full mt-3 py-3"
          style={{ background: "#fff", color: C.muted, border: `1.5px solid ${C.line}`, fontWeight: 700, fontSize: 15 }}>
          {copied ? "リンクをコピーしました ✓" : "🔗 このゲームのリンクを共有"}
        </button>
      </div></div>
    );
  }

  // ── 会話カード：設定 ──
  if (phase === "cardsSetup") {
    return (
      <div style={bg}><div style={wrap}>
        <button onClick={goHome} className="mb-2" style={{ background: "none", border: "none", color: C.muted, fontWeight: 700, fontSize: 14, padding: "4px 2px" }}>← モード選択にもどる</button>
        <div style={{ textAlign: "center", fontSize: 40, marginTop: 4 }}>🃏</div>
        <h1 style={{ fontSize: 28, fontWeight: 800, textAlign: "center", lineHeight: 1.25, marginTop: 4 }}>会話カード</h1>
        <p style={{ textAlign: "center", color: C.muted, marginTop: 6, marginBottom: 16, lineHeight: 1.6 }}>
          質問カードを1枚ずつめくって、<b>話の種</b>に。<br />当てっこ無しで、気軽におしゃべりしよう。
        </p>
        <div className="rounded-3xl p-5" style={{ background: "#fff", boxShadow: "0 10px 30px rgba(51,40,58,.08)" }}>
          <div style={{ fontSize: 13, color: C.ink, fontWeight: 700, marginBottom: 8 }}>深さ</div>
          <div className="flex flex-col gap-2">
            {MODES.map((m) => {
              const on = mode === m.key;
              return (
                <button key={m.key} onClick={() => setMode(m.key)} className="rounded-2xl px-4 py-3 text-left"
                  style={{ border: `2px solid ${on ? C.ink : C.line}`, background: on ? C.ink : "#fff" }}>
                  <div style={{ fontSize: 16, fontWeight: 800, color: on ? "#fff" : C.ink }}>{m.label}</div>
                  <div style={{ fontSize: 12, color: on ? "#EAD9DF" : C.muted, marginTop: 2 }}>{m.desc}</div>
                </button>
              );
            })}
          </div>
          <div style={{ fontSize: 13, color: C.ink, fontWeight: 700, marginTop: 18, marginBottom: 8 }}>カテゴリ{spicyUnlocked ? " 🔓" : ""}</div>
          <div className="flex flex-wrap gap-2">
            {(spicyUnlocked ? [...CATEGORIES, CAT_SPICY] : CATEGORIES).map((c) => {
              const on = category === c;
              return (
                <button key={c} onClick={() => {
                  setCategory(c);
                  if (c === CAT_LOVE && !spicyUnlocked) {
                    const n = loveTaps + 1; setLoveTaps(n);
                    if (n >= 20) { setSpicyUnlocked(true); try { window.storage.set("spicy-unlocked", "1"); } catch (e) {} }
                  }
                }} className="rounded-full px-4 py-2"
                  style={{ fontSize: 14, fontWeight: 700, border: `1.5px solid ${on ? C.ink : C.line}`, background: on ? C.ink : "#fff", color: on ? "#fff" : C.muted }}>{c}</button>
              );
            })}
          </div>
          {category === CAT_SPICY && (
            <div style={{ fontSize: 12, color: C.muted, marginTop: 8 }}>※18歳以上向け。大人同士で楽しんでね</div>
          )}
        </div>
        <button onClick={startCards} className="rounded-full w-full mt-5 py-4"
          style={{ background: C.ink, color: "#fff", fontWeight: 800, fontSize: 17 }}>カードをめくる</button>
      </div></div>
    );
  }

  // ── 会話カード：カードめくり ──
  if (phase === "cards") {
    const card = deck[cardIdx] || null;
    const catColor = category === CAT_LOVE || category === CAT_SPICY ? C.a : C.b;
    return (
      <div style={bg}><div style={wrap}>
        <div className="flex items-center justify-between mb-3">
          <button onClick={goHome} style={{ background: "none", border: "none", color: C.muted, fontWeight: 700, fontSize: 14, padding: "4px 2px" }}>← ホーム</button>
          <span className="rounded-full px-3 py-1" style={{ fontSize: 12, fontWeight: 800, background: "#fff", color: C.muted, border: `1px solid ${C.line}` }}>
            {MODES.find((m) => m.key === mode)?.label} ・ {category}
          </span>
        </div>
        {card ? (
          <>
            <style>{`
              @keyframes cardPera {
                0%   { transform: rotateX(-85deg); opacity: 0; box-shadow: 0 30px 44px rgba(51,40,58,.22); }
                55%  { transform: rotateX(9deg);   opacity: 1; }
                80%  { transform: rotateX(-3deg); }
                100% { transform: rotateX(0deg);   box-shadow: 0 12px 34px rgba(51,40,58,.12); }
              }
              @media (prefers-reduced-motion: reduce) {
                .pera-card { animation: none !important; }
              }
            `}</style>
            <div style={{ perspective: 900 }}>
              <div key={flipKey} className="pera-card rounded-3xl" style={{ background: "#fff", boxShadow: "0 12px 34px rgba(51,40,58,.12)", border: `1px solid ${C.line}`, padding: "28px 22px", minHeight: 260, display: "flex", flexDirection: "column", transformOrigin: "top center", backfaceVisibility: "hidden", animation: "cardPera .44s cubic-bezier(.2,.8,.25,1) both" }}>
                <div className="flex items-center justify-between">
                  <span className="rounded-full px-3 py-1" style={{ fontSize: 12, fontWeight: 800, background: catColor, color: "#fff" }}>話の種</span>
                  <span style={{ fontSize: 13, color: C.muted, fontWeight: 700, fontVariantNumeric: "tabular-nums" }}>{cardIdx + 1} / {deck.length}</span>
                </div>
                <div className="flex-1 flex items-center justify-center" style={{ padding: "18px 0" }}>
                  <div style={{ fontSize: 24, fontWeight: 800, color: C.ink, textAlign: "center", lineHeight: 1.5 }}>{card.question}</div>
                </div>
                {Array.isArray(card.choices) && card.choices.length > 0 && (
                  <div className="flex flex-wrap justify-center gap-2" style={{ marginTop: 4 }}>
                    {card.choices.map((ch, i) => (
                      <span key={i} className="rounded-full px-3 py-1" style={{ fontSize: 13, fontWeight: 700, background: C.aSoft, color: C.ink, opacity: 0.85 }}>{ch}</span>
                    ))}
                  </div>
                )}
              </div>
            </div>
            <div style={{ textAlign: "center", fontSize: 12.5, color: C.muted, marginTop: 12, lineHeight: 1.6 }}>
              選択肢はあくまでヒント。自由に話してOK 🗣️
            </div>
            <div className="flex gap-3 mt-4">
              <button onClick={prevCard} disabled={cardIdx === 0} className="rounded-full px-5 py-4"
                style={{ background: "#fff", color: C.muted, border: `1.5px solid ${C.line}`, fontWeight: 700, opacity: cardIdx === 0 ? 0.4 : 1 }}>← 前</button>
              <button onClick={nextCard} className="rounded-full flex-1 py-4" style={{ background: C.ink, color: "#fff", fontWeight: 800, fontSize: 17 }}>次のカード →</button>
            </div>
            <button onClick={shuffleCards} className="rounded-full w-full mt-3 py-3" style={{ background: "#fff", color: C.muted, border: `1.5px solid ${C.line}`, fontWeight: 700 }}>🔀 シャッフル</button>
          </>
        ) : (
          <div className="rounded-3xl" style={{ background: "#fff", boxShadow: "0 12px 34px rgba(51,40,58,.12)", padding: "40px 22px", textAlign: "center" }}>
            <div style={{ fontSize: 30 }}>🕊️</div>
            <div style={{ marginTop: 10, color: C.muted, fontWeight: 700, lineHeight: 1.6 }}>このカテゴリのカードが見つかりませんでした。<br />別のカテゴリを選んでね。</div>
            <button onClick={() => setPhase("cardsSetup")} className="rounded-full w-full mt-5 py-3" style={{ background: C.ink, color: "#fff", fontWeight: 800, fontSize: 16 }}>カテゴリを選びなおす</button>
          </div>
        )}
      </div></div>
    );
  }

  // ── LOADING ──
  if (phase === "gen") {
    return (
      <div style={{ ...bg, display: "flex", alignItems: "center", justifyContent: "center" }}>
        <div style={{ textAlign: "center" }}>
          <div style={{ fontSize: 40 }}>💗</div>
          <div style={{ marginTop: 10, color: C.muted, fontWeight: 700 }}>問題をつくっています…</div>
        </div>
      </div>
    );
  }

  // ── HANDOFFS ──
  if (phase === "introOwnA")
    return <Handoff tag="STEP 1 ・ 本音を入力" name={nameA} color={C.a}
      subtitle={<>選択肢から自分の答えを選んでね。<br />相手には見せないで！</>}
      onStart={() => setPhase("ownA")} bg={bg} wrap={wrap} />;
  if (phase === "introOwnB")
    return <Handoff tag="STEP 1 ・ 本音を入力" name={nameB} color={C.b}
      subtitle={<>{nameA} が回答おわり。<br />同じ質問に、選択肢から自分の答えを選んでね。</>}
      onStart={() => setPhase("ownB")} bg={bg} wrap={wrap} />;
  if (phase === "introGuessA")
    return <Handoff tag="STEP 2 ・ 相手を予想" name={nameA} color={C.a}
      subtitle={<>{nameB} の答えを選択式で予想！<br />どれが本物か当ててね。</>}
      onStart={() => setPhase("guessA")} bg={bg} wrap={wrap} />;
  if (phase === "introGuessB")
    return <Handoff tag="STEP 2 ・ 相手を予想" name={nameB} color={C.b}
      subtitle={<>{nameA} の答えを選択式で予想！<br />どれが本物か当ててね。</>}
      onStart={() => setPhase("guessB")} bg={bg} wrap={wrap} />;

  // ── OWN ROUNDS ──
  if (phase === "ownA")
    return <div style={bg}><div style={wrap}>
      <OwnRound player={nameA} color={C.a} mode={mode} category={category} questions={questions}
        onDone={(finalQ, ans) => { setQA(finalQ); setOwnA(ans); setPhase("introOwnB"); }} />
    </div></div>;
  if (phase === "ownB")
    return <div style={bg}><div style={wrap}>
      <OwnRound player={nameB} color={C.b} mode={mode} category={category} questions={questions}
        onDone={(finalQ, ans) => { setQB(finalQ); setOwnB(ans); startGuessing(qA, ownA, finalQ, ans); }} />
    </div></div>;

  // ── GUESS ROUNDS ──（Aは Bの質問を、Bは Aの質問を予想）
  if (phase === "guessA")
    return <div style={bg}><div style={wrap}>
      <GuessRound player={nameA} other={nameB} color={C.a} otherColor={C.b}
        questions={qB} options={optsForA}
        onDone={(picks) => { setGuessA(picks); setPhase("introGuessB"); }} />
    </div></div>;
  if (phase === "guessB")
    return <div style={bg}><div style={wrap}>
      <GuessRound player={nameB} other={nameA} color={C.b} otherColor={C.a}
        questions={qA} options={optsForB}
        onDone={(picks) => { setGuessB(picks); setPhase("results"); }} />
    </div></div>;

  // ── RESULTS ──
  if (phase === "results" && guessA && guessB) {
    const n = Math.min(qA.length, qB.length);
    const rows = Array.from({ length: n }).map((_, i) => ({
      qAq: qA[i].question, qBq: qB[i].question, same: qA[i].question === qB[i].question,
      aOwn: ownA[i], bOwn: ownB[i], aGuessB: guessA[i], bGuessA: guessB[i],
      aRight: guessA[i] === ownB[i], bRight: guessB[i] === ownA[i],
    }));
    const scoreA = rows.filter((r) => r.aRight).length;
    const scoreB = rows.filter((r) => r.bRight).length;
    const total = rows.length * 2;
    const pct = Math.round(((scoreA + scoreB) / total) * 100);
    const tier = tierFor(scoreA, scoreB);
    const chip = (text, right, color) => (
      <span className="inline-flex items-center gap-1 rounded-full px-3 py-1"
        style={{ fontSize: 13, fontWeight: 700, background: right ? "#FBF1DC" : "#F5EEF1", color: right ? C.gold : C.muted, border: `1px solid ${right ? C.gold : C.line}` }}>
        {right ? "◎" : "×"} {text}
      </span>
    );
    const tag = (name, color, soft) => (
      <span className="rounded-full px-2 py-1" style={{ background: soft, color, fontSize: 12, fontWeight: 800, whiteSpace: "nowrap" }}>{name}</span>
    );
    return (
      <div style={bg}><div style={wrap}>
        <div className="flex flex-col items-center" style={{ marginTop: 8 }}>
          <TierSprite tier={tier} />
          <div style={{ fontSize: 20, fontWeight: 800, marginTop: 6 }}>{tier.name}</div>
        </div>
        <div style={{ textAlign: "center", marginTop: 6 }}>
          <div style={{ fontSize: 40, fontWeight: 800, color: C.gold, lineHeight: 1 }}>{pct}%</div>
          <div style={{ fontSize: 13, color: C.muted, fontWeight: 700, marginTop: 2 }}>相性スコア</div>
          <div style={{ fontSize: 15, fontWeight: 700, marginTop: 10, lineHeight: 1.7 }}>{tier.msg}</div>
        </div>
        <div className="flex gap-3 mt-5">
          <div className="flex-1 rounded-2xl p-4" style={{ background: "#fff", boxShadow: "0 6px 20px rgba(51,40,58,.06)" }}>
            <div className="flex items-center gap-2" style={{ fontSize: 13, color: C.a, fontWeight: 700 }}><Dot color={C.a} /> {nameA}</div>
            <div style={{ fontSize: 22, fontWeight: 800, marginTop: 4 }}>{scoreA}<span style={{ fontSize: 14, color: C.muted }}> / {rows.length}</span></div>
            <div style={{ fontSize: 12, color: C.muted }}>{nameB} を的中</div>
          </div>
          <div className="flex-1 rounded-2xl p-4" style={{ background: "#fff", boxShadow: "0 6px 20px rgba(51,40,58,.06)" }}>
            <div className="flex items-center gap-2" style={{ fontSize: 13, color: C.b, fontWeight: 700 }}><Dot color={C.b} /> {nameB}</div>
            <div style={{ fontSize: 22, fontWeight: 800, marginTop: 4 }}>{scoreB}<span style={{ fontSize: 14, color: C.muted }}> / {rows.length}</span></div>
            <div style={{ fontSize: 12, color: C.muted }}>{nameA} を的中</div>
          </div>
        </div>
        <div style={{ fontSize: 13, color: C.muted, fontWeight: 700, margin: "22px 4px 10px" }}>答え合わせ</div>
        <div className="flex flex-col gap-3">
          {rows.map((r, i) => (
            <div key={i} className="rounded-2xl p-4" style={{ background: "#fff", boxShadow: "0 6px 20px rgba(51,40,58,.05)" }}>
              {r.same ? (
                <>
                  <div style={{ fontSize: 15, fontWeight: 800, marginBottom: 10 }}><span style={{ color: C.muted }}>Q{i + 1}. </span>{r.qAq}</div>
                  <div className="flex items-start gap-2" style={{ marginBottom: 8 }}>
                    <span className="mt-1">{tag(nameA, C.a, C.aSoft)}</span>
                    <div className="flex-1">
                      <div style={{ fontSize: 15, fontWeight: 700 }}><span style={{ fontSize: 12, color: C.muted, fontWeight: 700 }}>の答え：</span>{r.aOwn || "—"}</div>
                      <div className="mt-1">{chip(`${nameB}の予想「${r.bGuessA || "—"}」`, r.bRight, C.b)}</div>
                    </div>
                  </div>
                  <div className="flex items-start gap-2">
                    <span className="mt-1">{tag(nameB, C.b, C.bSoft)}</span>
                    <div className="flex-1">
                      <div style={{ fontSize: 15, fontWeight: 700 }}><span style={{ fontSize: 12, color: C.muted, fontWeight: 700 }}>の答え：</span>{r.bOwn || "—"}</div>
                      <div className="mt-1">{chip(`${nameA}の予想「${r.aGuessB || "—"}」`, r.aRight, C.a)}</div>
                    </div>
                  </div>
                </>
              ) : (
                <>
                  <div style={{ fontSize: 12, color: C.muted, fontWeight: 700, marginBottom: 2 }}>Q{i + 1}</div>
                  <div className="flex items-start gap-2" style={{ marginBottom: 10 }}>
                    <span className="mt-1">{tag(nameA, C.a, C.aSoft)}</span>
                    <div className="flex-1">
                      <div style={{ fontSize: 13, color: C.muted }}>{r.qAq}</div>
                      <div style={{ fontSize: 15, fontWeight: 700 }}>{r.aOwn || "—"}</div>
                      <div className="mt-1">{chip(`${nameB}の予想「${r.bGuessA || "—"}」`, r.bRight, C.b)}</div>
                    </div>
                  </div>
                  <div className="flex items-start gap-2">
                    <span className="mt-1">{tag(nameB, C.b, C.bSoft)}</span>
                    <div className="flex-1">
                      <div style={{ fontSize: 13, color: C.muted }}>{r.qBq}</div>
                      <div style={{ fontSize: 15, fontWeight: 700 }}>{r.bOwn || "—"}</div>
                      <div className="mt-1">{chip(`${nameA}の予想「${r.aGuessB || "—"}」`, r.aRight, C.a)}</div>
                    </div>
                  </div>
                </>
              )}
            </div>
          ))}
        </div>
        <div className="flex gap-3 mt-6">
          <button onClick={replay} className="rounded-full flex-1 py-3" style={{ background: C.ink, color: "#fff", fontWeight: 800, fontSize: 16 }}>もう一回（同じ2人）</button>
          <button onClick={reset} className="rounded-full px-5 py-3" style={{ background: "#fff", color: C.muted, border: `1.5px solid ${C.line}`, fontWeight: 700 }}>最初から</button>
        </div>
        <button onClick={shareApp} className="rounded-full w-full mt-3 py-3"
          style={{ background: "#fff", color: C.a, border: `1.5px solid ${C.a}`, fontWeight: 800, fontSize: 15 }}>
          {copied ? "リンクをコピーしました ✓" : "🔗 友達にこのゲームを共有"}
        </button>
      </div></div>
    );
  }

  return null;
}
